<?php
require_once __DIR__.'/app/lib/Db.php';
$config=require __DIR__.'/app/config.php';
$pdo=Db::pdo();
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function initials($name){$parts=preg_split('/\s+/',trim((string)$name));$out='';foreach(array_slice($parts,0,2) as $x){if($x!=='')$out.=mb_strtoupper(mb_substr($x,0,1));}return $out?:'TS';}
function valid_logo($path){if(!$path||!str_starts_with($path,'/media/software/')||str_contains($path,'..'))return null;$full=__DIR__.$path;return is_file($full)?$path:null;}
if(!preg_match('#^/categories/([a-z0-9-]+)/?$#',$path,$m)){http_response_code(404);exit('Not found');}
$st=$pdo->prepare('SELECT id,name,slug,description FROM categories WHERE slug=? AND is_active=1 LIMIT 1');$st->execute([$m[1]]);$c=$st->fetch();if(!$c){http_response_code(404);exit('Not found');}
$p=$pdo->prepare("SELECT p.id,p.name,p.slug,p.short_description,p.logo_path,p.last_reviewed_at,v.name vendor,COUNT(DISTINCT CASE WHEN pc.support_status NOT IN('unknown','not_yet_verified') THEN pc.id END) verified_count,COUNT(DISTINCT CASE WHEN pc.support_status='supported' THEN pc.id END) supported_count,COUNT(DISTINCT es.id) evidence_count FROM products p LEFT JOIN vendors v ON v.id=p.vendor_id LEFT JOIN product_capabilities pc ON pc.product_id=p.id AND pc.edition_id IS NULL LEFT JOIN evidence_sources es ON es.product_id=p.id WHERE p.category_id=? AND p.status='active' GROUP BY p.id ORDER BY p.name");$p->execute([$c['id']]);$products=$p->fetchAll();
$cap=$pdo->prepare("SELECT cp.name,cp.slug,mo.name module,COUNT(DISTINCT CASE WHEN pc.support_status='supported' THEN pc.product_id END) supported_products FROM capabilities cp JOIN modules mo ON mo.id=cp.module_id LEFT JOIN product_capabilities pc ON pc.capability_id=cp.id AND pc.edition_id IS NULL WHERE mo.category_id=? AND cp.is_active=1 GROUP BY cp.id,cp.name,cp.slug,mo.name ORDER BY mo.name,cp.name");$cap->execute([$c['id']]);$caps=$cap->fetchAll();
$desc=$c['description']?:('Compare '.$c['name'].' software using evidence-backed capabilities, integrations, deployment and product data.');
$canonical=rtrim($config['site_url'],'/').'/categories/'.$c['slug'];
$itemLd=[];foreach($products as $i=>$x)$itemLd[]=['@type'=>'ListItem','position'=>$i+1,'url'=>rtrim($config['site_url'],'/').'/software/'.$x['slug'],'name'=>$x['name']];
$ld=['@context'=>'https://schema.org','@type'=>'ItemList','name'=>$c['name'].' software','itemListElement'=>$itemLd];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($c['name'])?> Software Guide & Comparison | TechSelectAI</title><meta name="description" content="<?=e($desc)?>"><link rel="canonical" href="<?=e($canonical)?>"><meta property="og:title" content="<?=e($c['name'])?> Software Guide | TechSelectAI"><meta property="og:description" content="<?=e($desc)?>"><meta property="og:url" content="<?=e($canonical)?>"><script type="application/ld+json"><?=json_encode($ld,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script><style>:root{--navy:#123b67;--ink:#172033;--muted:#64748b;--line:#e2e8f0;--soft:#f7fafc}*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:#fff}a{color:#145ea8}header{display:flex;justify-content:space-between;align-items:center;padding:17px max(24px,5vw);border-bottom:1px solid var(--line)}header>a{font-size:20px;font-weight:800;color:var(--navy);text-decoration:none}nav a{margin-left:20px;text-decoration:none;font-weight:650;color:#334155}.wrap{max-width:1160px;margin:auto;padding:0 24px}.crumbs{font-size:13px;color:var(--muted);padding-top:25px}.hero{padding:38px 0 20px}.eyebrow{font-size:12px;letter-spacing:.09em;text-transform:uppercase;color:#52708b;font-weight:800}.hero h1{font-size:clamp(36px,5vw,58px);line-height:1.03;margin:8px 0 13px}.lead{font-size:19px;line-height:1.65;color:#536174;max-width:900px}.stats{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.pill{padding:8px 11px;border-radius:999px;background:#f1f6f9;color:#31516e;font-size:13px;font-weight:700}.section{padding-top:34px}.section h2{font-size:28px;margin:0 0 8px}.intro{color:var(--muted);margin:0 0 18px;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}.card{border:1px solid var(--line);border-radius:15px;padding:18px;background:#fff;color:inherit;text-decoration:none}.product{display:flex;gap:15px;align-items:flex-start}.mark{width:58px;height:58px;border-radius:14px;border:1px solid #dbe5ec;background:#f4f8fa;display:grid;place-items:center;overflow:hidden;flex:0 0 auto;color:var(--navy);font-weight:850}.mark img{width:100%;height:100%;object-fit:contain;padding:7px}.card h3{margin:0 0 6px;font-size:18px}.card p{margin:5px 0;color:var(--muted);line-height:1.45}.meta{font-size:12px;color:#657487}.compare{display:inline-block;margin-top:10px;font-weight:700}.cap-card{border:1px solid var(--line);border-radius:13px;padding:15px;text-decoration:none;color:inherit;background:var(--soft)}.cap-card h3{font-size:16px;margin:3px 0 6px}.cta{margin:42px 0 0;padding:26px;border-radius:17px;background:linear-gradient(135deg,#f0f8fb,#f5f8fc);border:1px solid #d5e5ed}.btn{display:inline-block;margin-top:8px;padding:11px 16px;border-radius:10px;background:var(--navy);color:#fff;text-decoration:none;font-weight:750}footer{margin:56px 0 30px;color:var(--muted);font-size:13px}@media(max-width:650px){nav{display:none}}</style></head><body><header><a href="/">TechSelectAI</a><nav><a href="/software">Software</a><a href="/methodology">Methodology</a><a href="/">Get Advice</a></nav></header><main class="wrap"><div class="crumbs"><a href="/">Home</a> / Software categories / <?=e($c['name'])?></div><section class="hero"><div class="eyebrow">Software category</div><h1><?=e($c['name'])?></h1><p class="lead"><?=e($desc)?></p><div class="stats"><span class="pill"><?=count($products)?> active products</span><span class="pill"><?=count($caps)?> tracked capabilities</span></div></section><section class="section"><h2>Products in this category</h2><p class="intro">Open any product for evidence-backed capabilities, integrations, deployment options, pricing where verified, and alternatives.</p><div class="grid"><?php foreach($products as $x):$logo=valid_logo($x['logo_path']);?><article class="card"><div class="product"><div class="mark"><?php if($logo):?><img src="<?=e($logo)?>" alt="<?=e($x['name'])?> logo"><?php else:?><?=e(initials($x['name']))?><?php endif;?></div><div><div class="eyebrow"><?=e($x['vendor']?:'Vendor not recorded')?></div><h3><a href="/software/<?=e($x['slug'])?>"><?=e($x['name'])?></a></h3><p><?=e($x['short_description']?:'Evidence-backed product profile.')?></p><div class="meta"><?=intval($x['verified_count'])?> verified capabilities · <?=intval($x['supported_count'])?> supported · <?=intval($x['evidence_count'])?> evidence sources</div></div></div><a class="compare" href="/software/<?=e($x['slug'])?>">Review product →</a></article><?php endforeach;?></div></section><section class="section"><h2>Capabilities buyers commonly evaluate</h2><p class="intro">Use these pages to compare recorded support across products. Unknown means not yet verified, not unsupported.</p><div class="grid"><?php foreach($caps as $x):?><a class="cap-card" href="/capabilities/<?=e($x['slug'])?>"><div class="eyebrow"><?=e($x['module'])?></div><h3><?=e($x['name'])?></h3><p><?=intval($x['supported_products'])?> product<?=intval($x['supported_products'])===1?'':'s'?> currently recorded as supported</p></a><?php endforeach;?></div></section><section class="cta"><div class="eyebrow">Independent software advice</div><h2>Which <?=e($c['name'])?> product fits your company?</h2><p>TechSelectAI can evaluate products against your must-have capabilities, integrations, deployment constraints, security requirements, region and budget.</p><a class="btn" href="/?considering=<?=rawurlencode($c['name'])?>">Get software advice</a></section><footer>TechSelectAI uses evidence-backed product data. Vendor names and trademarks belong to their respective owners.</footer></main></body></html>